<?php namespace App\Jobs; use App\Models\Booking; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\DB; class ExpireBookingJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=3; public array $backoff=[10,30,90]; public function __construct(public int $bookingId){} public function handle():void{DB::transaction(function(){ $b=Booking::whereKey($this->bookingId)->lockForUpdate()->first(); if($b&&$b->status->value==='reserved'&&$b->expires_at&&$b->expires_at->isPast()){$b->update(['status'=>'expired']); Cache::tags(['events'])->flush();}});}}
